namespace ResearchAgent;

/// <summary>
/// Simple in-memory note-taking service that stores research findings.
/// </summary>
public sealed class NoteService
{
    private readonly List<string> _notes = [];

    public void AddNote(string note)
    {
        _notes.Add(note);
    }

    public IReadOnlyList<string> GetNotes() => _notes.AsReadOnly();

    public string GetSummaryPrompt()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        return "Here are the research notes collected so far:\n" +
               string.Join("\n- ", ["", .. _notes]);
    }
}

using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Tools available to the research agent.
/// </summary>
public sealed class ResearchTools(NoteService noteService)
{
    private static readonly HttpClient HttpClient = new();

    [Description("Search the web for information on a given query. Returns a list of relevant result titles and snippets.")]
    public async Task<string> WebSearch(
        [Description("The search query to look up")] string query)
    {
        // Uses DuckDuckGo Instant Answer API (no key required)
        var encodedQuery = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1";

        try
        {
            var response = await HttpClient.GetFromJsonAsync<JsonElement>(url);
            var results = new List<string>();

            // Extract abstract
            var abstractText = response.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                var source = response.GetProperty("AbstractSource").GetString();
                results.Add($"[{source}] {abstractText}");
            }

            // Extract related topics
            if (response.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                    {
                        var snippet = text.GetString();
                        if (!string.IsNullOrWhiteSpace(snippet))
                            results.Add(snippet);
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try rephrasing the search.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note capturing a key finding or piece of information discovered during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        noteService.AddNote(note);
        var count = noteService.GetNotes().Count;
        return $"Note saved (total notes: {count}).";
    }

    [Description("Retrieve all research notes taken so far.")]
    public string GetNotes()
    {
        var notes = noteService.GetNotes();
        if (notes.Count == 0)
            return "No notes taken yet.";

        return string.Join("\n", notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    /// <summary>
    /// Returns the list of AITools for registration with the agent.
    /// </summary>
    public IList<AITool> AsTools() =>
    [
        AIFunctionFactory.Create(WebSearch, nameof(WebSearch), "Search the web for information on a given query."),
        AIFunctionFactory.Create(TakeNote, nameof(TakeNote), "Save a research note with a key finding."),
        AIFunctionFactory.Create(GetNotes, nameof(GetNotes), "Retrieve all research notes taken so far."),
    ];
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace ResearchAgent;

/// <summary>
/// Hosted service that runs the research agent workflow.
/// </summary>
public sealed class ResearchWorker(
    IChatClient chatClient,
    ResearchTools tools,
    NoteService noteService,
    IHostApplicationLifetime lifetime,
    ILogger<ResearchWorker> logger) : BackgroundService
{
    private const int MaxIterations = 10;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine("=== Research Agent ===");
        Console.Write("Enter a topic to research: ");
        var topic = Console.ReadLine();

        if (string.IsNullOrWhiteSpace(topic))
        {
            Console.WriteLine("No topic provided. Exiting.");
            lifetime.StopApplication();
            return;
        }

        Console.WriteLine($"\nResearching: {topic}\n");

        await RunAgentLoop(topic, stoppingToken);

        // Summarize findings
        Console.WriteLine("\n=== Research Summary ===\n");
        var summary = await SummarizeFindings(topic, stoppingToken);
        Console.WriteLine(summary);

        Console.WriteLine("\n=== Notes Collected ===");
        foreach (var note in noteService.GetNotes())
        {
            Console.WriteLine($"  • {note}");
        }

        lifetime.StopApplication();
    }

    private async Task RunAgentLoop(string topic, CancellationToken ct)
    {
        var systemPrompt = $"""
            You are a research agent. Your goal is to research the following topic thoroughly: "{topic}"

            You have access to tools:
            - WebSearch: Search the web for information
            - TakeNote: Save important findings as notes
            - GetNotes: Review your collected notes

            Strategy:
            1. Search for the topic from multiple angles
            2. Take notes on key findings as you discover them
            3. When you have gathered enough information (at least 3-5 key findings), stop searching

            Be thorough but efficient. Take notes on the most important and interesting findings.
            When you are done researching, respond with "RESEARCH COMPLETE" in your final message.
            """;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, systemPrompt),
            new(ChatRole.User, $"Please research this topic: {topic}"),
        };

        var options = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 1024,
            Tools = tools.AsTools(),
            ToolMode = ChatToolMode.Auto,
        };

        for (var i = 0; i < MaxIterations; i++)
        {
            logger.LogDebug("Agent iteration {Iteration}/{Max}", i + 1, MaxIterations);

            ChatResponse response;
            try
            {
                response = await chatClient.GetResponseAsync(messages, options, ct);
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Error during agent iteration {Iteration}", i + 1);
                break;
            }

            // Add all response messages to history
            messages.AddMessages(response);

            var lastContent = response.Messages.LastOrDefault()?.Text ?? "";
            if (!string.IsNullOrEmpty(lastContent))
            {
                Console.WriteLine($"[Agent] {lastContent}");
            }

            // Check if the agent considers research complete
            if (lastContent.Contains("RESEARCH COMPLETE", StringComparison.OrdinalIgnoreCase))
            {
                logger.LogInformation("Agent completed research in {Iterations} iterations", i + 1);
                break;
            }

            // If no tool calls were made in this turn, the agent is done
            var hasToolCalls = response.Messages.Any(m =>
                m.Contents.Any(c => c is FunctionCallContent));
            if (!hasToolCalls && i > 0)
            {
                logger.LogInformation("Agent stopped making tool calls after {Iterations} iterations", i + 1);
                break;
            }
        }
    }

    private async Task<string> SummarizeFindings(string topic, CancellationToken ct)
    {
        var notesContext = noteService.GetSummaryPrompt();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a research summarizer. Provide a clear, well-structured summary of the research findings."),
            new(ChatRole.User, $"""
                Please summarize the research findings on "{topic}".

                {notesContext}

                Provide a concise but comprehensive summary with key takeaways.
                """),
        };

        var options = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        };

        var response = await chatClient.GetResponseAsync(messages, options, ct);
        return response.Text ?? "Unable to generate summary.";
    }
}

