using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Tools available to the research agent.
/// </summary>
public sealed class ResearchTools(NoteService noteService)
{
    private static readonly HttpClient HttpClient = new();

    [Description("Search the web for information on a given query. Returns a list of relevant result titles and snippets.")]
    public async Task<string> WebSearch(
        [Description("The search query to look up")] string query)
    {
        // Uses DuckDuckGo Instant Answer API (no key required)
        var encodedQuery = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1";

        try
        {
            var response = await HttpClient.GetFromJsonAsync<JsonElement>(url);
            var results = new List<string>();

            // Extract abstract
            var abstractText = response.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                var source = response.GetProperty("AbstractSource").GetString();
                results.Add($"[{source}] {abstractText}");
            }

            // Extract related topics
            if (response.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                    {
                        var snippet = text.GetString();
                        if (!string.IsNullOrWhiteSpace(snippet))
                            results.Add(snippet);
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try rephrasing the search.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note capturing a key finding or piece of information discovered during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        noteService.AddNote(note);
        var count = noteService.GetNotes().Count;
        return $"Note saved (total notes: {count}).";
    }

    [Description("Retrieve all research notes taken so far.")]
    public string GetNotes()
    {
        var notes = noteService.GetNotes();
        if (notes.Count == 0)
            return "No notes taken yet.";

        return string.Join("\n", notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    /// <summary>
    /// Returns the list of AITools for registration with the agent.
    /// </summary>
    public IList<AITool> AsTools() =>
    [
        AIFunctionFactory.Create(WebSearch, nameof(WebSearch), "Search the web for information on a given query."),
        AIFunctionFactory.Create(TakeNote, nameof(TakeNote), "Save a research note with a key finding."),
        AIFunctionFactory.Create(GetNotes, nameof(GetNotes), "Retrieve all research notes taken so far."),
    ];
}

