using Microsoft.Extensions.AI;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace ResearchAgent;

/// <summary>
/// Hosted service that runs the research agent workflow.
/// </summary>
public sealed class ResearchWorker(
    IChatClient chatClient,
    ResearchTools tools,
    NoteService noteService,
    IHostApplicationLifetime lifetime,
    ILogger<ResearchWorker> logger) : BackgroundService
{
    private const int MaxIterations = 10;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine("=== Research Agent ===");
        Console.Write("Enter a topic to research: ");
        var topic = Console.ReadLine();

        if (string.IsNullOrWhiteSpace(topic))
        {
            Console.WriteLine("No topic provided. Exiting.");
            lifetime.StopApplication();
            return;
        }

        Console.WriteLine($"\nResearching: {topic}\n");

        await RunAgentLoop(topic, stoppingToken);

        // Summarize findings
        Console.WriteLine("\n=== Research Summary ===\n");
        var summary = await SummarizeFindings(topic, stoppingToken);
        Console.WriteLine(summary);

        Console.WriteLine("\n=== Notes Collected ===");
        foreach (var note in noteService.GetNotes())
        {
            Console.WriteLine($"  • {note}");
        }

        lifetime.StopApplication();
    }

    private async Task RunAgentLoop(string topic, CancellationToken ct)
    {
        var systemPrompt = $"""
            You are a research agent. Your goal is to research the following topic thoroughly: "{topic}"

            You have access to tools:
            - WebSearch: Search the web for information
            - TakeNote: Save important findings as notes
            - GetNotes: Review your collected notes

            Strategy:
            1. Search for the topic from multiple angles
            2. Take notes on key findings as you discover them
            3. When you have gathered enough information (at least 3-5 key findings), stop searching

            Be thorough but efficient. Take notes on the most important and interesting findings.
            When you are done researching, respond with "RESEARCH COMPLETE" in your final message.
            """;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, systemPrompt),
            new(ChatRole.User, $"Please research this topic: {topic}"),
        };

        var options = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 1024,
            Tools = tools.AsTools(),
            ToolMode = ChatToolMode.Auto,
        };

        for (var i = 0; i < MaxIterations; i++)
        {
            logger.LogDebug("Agent iteration {Iteration}/{Max}", i + 1, MaxIterations);

            ChatResponse response;
            try
            {
                response = await chatClient.GetResponseAsync(messages, options, ct);
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Error during agent iteration {Iteration}", i + 1);
                break;
            }

