            messages.AddMessages(response);

            var lastContent = response.Messages.LastOrDefault()?.Text ?? "";
            if (!string.IsNullOrEmpty(lastContent))
            {
                Console.WriteLine($"[Agent] {lastContent}");
            }

            // Check if the agent considers research complete
            if (lastContent.Contains("RESEARCH COMPLETE", StringComparison.OrdinalIgnoreCase))
            {
                logger.LogInformation("Agent completed research in {Iterations} iterations", i + 1);
                break;
            }

            // If no tool calls were made in this turn, the agent is done
            var hasToolCalls = response.Messages.Any(m =>
                m.Contents.Any(c => c is FunctionCallContent));
            if (!hasToolCalls && i > 0)
            {
                logger.LogInformation("Agent stopped making tool calls after {Iterations} iterations", i + 1);
                break;
            }
        }
    }

    private async Task<string> SummarizeFindings(string topic, CancellationToken ct)
    {
        var notesContext = noteService.GetSummaryPrompt();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a research summarizer. Provide a clear, well-structured summary of the research findings."),
            new(ChatRole.User, $"""
                Please summarize the research findings on "{topic}".

                {notesContext}

                Provide a concise but comprehensive summary with key takeaways.
                """),
        };

        var options = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        };

        var response = await chatClient.GetResponseAsync(messages, options, ct);
        return response.Text ?? "Unable to generate summary.";
    }
}

